import { readFile, writeFile, rename, mkdir } from "node:fs/promises";
import { dirname } from "node:path";
import { randomBytes } from "node:crypto";

// Books are kept in memory and written to a JSON file after every change.
// Writes go to a temp file first and are then renamed into place, so a crash
// mid-write never leaves a half-written books.json behind.
export async function openStore(file) {
  let books = [];
  try {
    books = JSON.parse(await readFile(file, "utf8"));
  } catch (err) {
    if (err.code !== "ENOENT") throw err;
  }

  let queue = Promise.resolve();
  function save() {
    // Serialize writes so two quick requests can't interleave.
    queue = queue.then(async () => {
      await mkdir(dirname(file), { recursive: true });
      const tmp = `${file}.${process.pid}.tmp`;
      await writeFile(tmp, JSON.stringify(books, null, 2));
      await rename(tmp, file);
    });
    return queue;
  }

  return {
    all: () => books,
    get: (id) => books.find((b) => b.id === id),

    async add({ title, author, notes }) {
      const book = {
        // Random, unguessable id: sharing one book's link doesn't let
        // someone walk through the rest of your list by counting up.
        id: randomBytes(6).toString("base64url"),
        title,
        author,
        notes,
        status: "reading",
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      await save();
      return book;
    },

    async finish(id) {
      const book = books.find((b) => b.id === id);
      if (!book) return null;
      if (book.status !== "finished") {
        book.status = "finished";
        book.finishedAt = new Date().toISOString();
        await save();
      }
      return book;
    },

    async updateNotes(id, notes) {
      const book = books.find((b) => b.id === id);
      if (!book) return null;
      book.notes = notes;
      await save();
      return book;
    },
  };
}

