// Everything the user typed is escaped before it goes into the page.
export function esc(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

const style = `
  body { font: 16px/1.5 system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; color: #222; }
  h1 a { color: inherit; text-decoration: none; }
  ul { padding: 0; list-style: none; }
  li { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: .5rem 0; border-bottom: 1px solid #eee; }
  .author, .muted { color: #666; }
  form.inline { margin: 0; }
  label { display: block; margin: .5rem 0 .2rem; }
  input, textarea { width: 100%; box-sizing: border-box; font: inherit; padding: .4rem; }
  textarea { min-height: 6rem; }
  button { font: inherit; padding: .3rem .8rem; margin-top: .5rem; cursor: pointer; }
  .notes { white-space: pre-wrap; background: #f7f7f7; padding: .75rem; border-radius: 4px; }
  .error { color: #b00020; }
`;

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)}</title>
<style>${style}</style>
</head>
<body>
<h1><a href="/">My books</a></h1>
${body}
</body>
</html>`;
}

function bookItem(book) {
  const finishButton =
    book.status === "reading"
      ? `<form class="inline" method="post" action="/books/${esc(book.id)}/finish">
           <button>Mark finished</button>
         </form>`
      : "";
  return `<li>
    <span><a href="/books/${esc(book.id)}">${esc(book.title)}</a>
      <span class="author">by ${esc(book.author)}</span></span>
    ${finishButton}
  </li>`;
}

function list(books, empty) {
  if (books.length === 0) return `<p class="muted">${empty}</p>`;
  return `<ul>${books.map(bookItem).join("")}</ul>`;
}

export function homePage(books, { error = "", values = {} } = {}) {
  const reading = books.filter((b) => b.status === "reading");
  const finished = books
    .filter((b) => b.status === "finished")
    .sort((a, b) => (b.finishedAt ?? "").localeCompare(a.finishedAt ?? ""));

  return layout(
    "My books",
    `
<h2>Currently reading</h2>
${list(reading, "Nothing on the go right now.")}

<h2>Finished</h2>
${list(finished, "No finished books yet.")}

<h2>Add a book</h2>
${error ? `<p class="error">${esc(error)}</p>` : ""}
<form method="post" action="/books">
  <label for="title">Title</label>
  <input id="title" name="title" required maxlength="300" value="${esc(values.title)}">
  <label for="author">Author</label>
  <input id="author" name="author" required maxlength="300" value="${esc(values.author)}">
  <label for="notes">Notes</label>
  <textarea id="notes" name="notes" maxlength="20000">${esc(values.notes)}</textarea>
  <button>Add book</button>
</form>`,
  );
}

export function bookPage(book) {
  const status =
    book.status === "finished"
      ? `Finished ${esc(book.finishedAt?.slice(0, 10))}`
      : "Currently reading";
  const finishButton =
    book.status === "reading"
      ? `<form method="post" action="/books/${esc(book.id)}/finish"><button>Mark finished</button></form>`
      : "";

  return layout(
    `${book.title} by ${book.author}`,
    `
<h2>${esc(book.title)}</h2>
<p class="author">by ${esc(book.author)}</p>
<p class="muted">${status}</p>
${finishButton}

<h3>Notes</h3>
${book.notes ? `<div class="notes">${esc(book.notes)}</div>` : `<p class="muted">No notes yet.</p>`}

<details>
  <summary>Edit notes</summary>
  <form method="post" action="/books/${esc(book.id)}/notes">
    <textarea name="notes" maxlength="20000" aria-label="Notes">${esc(book.notes)}</textarea>
    <button>Save notes</button>
  </form>
</details>

<p><a href="/">&larr; All books</a></p>`,
  );
}

export function notFoundPage() {
  return layout("Not found", `<p>That book isn't here.</p><p><a href="/">&larr; All books</a></p>`);
}

