const MAX_BODY = 64 * 1024;

function readForm(req) {
  return new Promise((resolve, reject) => {
    let body = "";
    req.setEncoding("utf8");
    req.on("data", (chunk) => {
      body += chunk;
      if (body.length > MAX_BODY) {
        reject(Object.assign(new Error("Form too large"), { status: 413 }));
        req.destroy();
      }
    });
    req.on("end", () => resolve(Object.fromEntries(new URLSearchParams(body))));
    req.on("error", reject);
  });
}

function send(res, status, html) {
  res.writeHead(status, { "Content-Type": "text/html; charset=utf-8" });
  res.end(html);
}

// After a form post, redirect so refreshing the page doesn't resubmit it.
function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

export function createHandler(store) {
  return async function handle(req, res) {
    try {
      const { pathname } = new URL(req.url, "http://localhost");
      const bookMatch = pathname.match(/^\/books\/([\w-]+)(?:\/(finish|notes))?\/?$/);

      if (req.method === "GET" && pathname === "/") {
        return send(res, 200, homePage(store.all()));
      }

      if (req.method === "POST" && pathname === "/books") {
        const form = await readForm(req);
        const title = (form.title ?? "").trim();
        const author = (form.author ?? "").trim();
        const notes = (form.notes ?? "").trim();
        if (!title || !author) {
          return send(
            res,
            400,
            homePage(store.all(), {
              error: "A book needs a title and an author.",
              values: { title, author, notes },
            }),
          );
        }
        const book = await store.add({ title, author, notes });
        return redirect(res, `/books/${book.id}`);
      }

      if (bookMatch) {
        const [, id, action] = bookMatch;

        if (req.method === "GET" && !action) {
          const book = store.get(id);
          return book ? send(res, 200, bookPage(book)) : send(res, 404, notFoundPage());
        }

        if (req.method === "POST" && action === "finish") {
          const book = await store.finish(id);
          if (!book) return send(res, 404, notFoundPage());
          // Go back to wherever the button was clicked (list or book page).
          const back = req.headers.referer;
          const sameSite = back && new URL(back).host === req.headers.host;
          return redirect(res, sameSite ? new URL(back).pathname : `/books/${id}`);
        }

        if (req.method === "POST" && action === "notes") {
          const form = await readForm(req);
          const book = await store.updateNotes(id, (form.notes ?? "").trim());
