import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { createServer } from "node:http";
import { mkdtemp, rm, readFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { openStore } from "../src/store.js";
import { createHandler } from "../src/app.js";

let dir, file, server, base;

async function start() {
  const store = await openStore(file);
  server = createServer(createHandler(store));
  await new Promise((r) => server.listen(0, "127.0.0.1", r));
  base = `http://127.0.0.1:${server.address().port}`;
}
const stop = () => new Promise((r) => server.close(r));

const post = (path, fields) =>
  fetch(base + path, {
    method: "POST",
    body: new URLSearchParams(fields),
    redirect: "manual",
  });

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), "books-"));
  file = join(dir, "books.json");
  await start();
});
afterEach(async () => {
  await stop();
  await rm(dir, { recursive: true, force: true });
});

describe("books app", () => {
  it("adds a book and shows it under currently reading", async () => {
    const res = await post("/books", { title: "Dune", author: "Frank Herbert", notes: "Spice." });
    expect(res.status).toBe(303);
    const bookUrl = res.headers.get("location");
    expect(bookUrl).toMatch(/^\/books\/[\w-]+$/);

    const home = await (await fetch(base + "/")).text();
    const [reading, finished] = home.split("<h2>Finished</h2>");
    expect(reading).toContain("Dune");
    expect(finished).not.toContain("Dune");

    const page = await (await fetch(base + bookUrl)).text();
    expect(page).toContain("Dune");
    expect(page).toContain("Frank Herbert");
    expect(page).toContain("Spice.");
  });

  it("marks a book finished", async () => {
    const id = (await post("/books", { title: "Emma", author: "Jane Austen" }))
      .headers.get("location").split("/").pop();
    const res = await post(`/books/${id}/finish`, {});
    expect(res.status).toBe(303);

    const home = await (await fetch(base + "/")).text();
    const [reading, finished] = home.split("<h2>Finished</h2>");
    expect(reading).not.toContain("Emma");
    expect(finished).toContain("Emma");
  });

  it("keeps books after a restart", async () => {
    const loc = (await post("/books", { title: "Beloved", author: "Toni Morrison" })).headers.get("location");
    await stop();
    await start();
    const res = await fetch(base + loc);
    expect(res.status).toBe(200);
    expect(await res.text()).toContain("Beloved");
    expect(JSON.parse(await readFile(file, "utf8"))).toHaveLength(1);
  });

  it("updates notes", async () => {
    const loc = (await post("/books", { title: "Ulysses", author: "James Joyce" })).headers.get("location");
    await post(`${loc}/notes`, { notes: "Hard going." });
    expect(await (await fetch(base + loc)).text()).toContain("Hard going.");
  });

  it("rejects a book without title or author", async () => {
    const res = await post("/books", { title: "", author: "Someone" });
    expect(res.status).toBe(400);
    expect(await res.text()).toContain("needs a title and an author");
  });

  it("escapes user input", async () => {
    const loc = (await post("/books", { title: "<script>alert(1)</script>", author: "x" })).headers.get("location");
    const page = await (await fetch(base + loc)).text();
    expect(page).not.toContain("<script>alert(1)</script>");
    expect(page).toContain("&lt;script&gt;");
  });

  it("returns 404 for an unknown book", async () => {
    expect((await fetch(base + "/books/nope")).status).toBe(404);
  });
});

